import{_ as t,a,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · Lesson 45 The power of the press","description":"学习 报告动词及其结构，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 45 The power of the press","description":"学习 报告动词及其结构，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 报告动词及其结构，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 44 Speed and comfort","link":"/life/english/new-concept/book-3/unit-03/lesson-044"},"next":{"text":"第三册：培养技能 · Lesson 46 Do it yourself","link":"/life/english/new-concept/book-3/unit-03/lesson-046"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 44 Speed and comfort","link":"/life/english/new-concept/book-3/unit-03/lesson-044"},"next":{"text":"第三册：培养技能 · Lesson 46 Do it yourself","link":"/life/english/new-concept/book-3/unit-03/lesson-046"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-03/lesson-045.md","filePath":"life/english/new-concept/book-3/unit-03/lesson-045.md"}'),i={name:"life/english/new-concept/book-3/unit-03/lesson-045.md"};function s(r,e,l,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第三册-培养技能-·-lesson-45-the-power-of-the-press" tabindex="-1">第三册：培养技能 · Lesson 45 The power of the press <a class="header-anchor" href="#第三册-培养技能-·-lesson-45-the-power-of-the-press" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 45 The power of the press&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>从媒体报道产生的影响讨论事实、引用和评价之间的距离。学习在转述中标明观点属于谁，避免把采访对象的判断当作作者立场。重点掌握不同报告动词后的结构，同时理解 claim、confirm、suggest 等词在证据程度和动作意图上的差异。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>headline</td><td>/ˈhedlaɪn/</td><td>n.</td><td>标题</td><td>a misleading headline</td></tr><tr><td>coverage</td><td>/ˈkʌvərɪdʒ/</td><td>n.</td><td>报道</td><td>media coverage</td></tr><tr><td>influence</td><td>/ˈɪnfluəns/</td><td>n.</td><td>影响</td><td>public influence</td></tr><tr><td>claim</td><td>/kleɪm/</td><td>v.</td><td>声称</td><td>claim responsibility</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>draw attention to — 引起对某问题的关注</li><li>make a distinction — 作出区分</li></ul><h2 id="语法讲解-报告动词及其结构" tabindex="-1">语法讲解：报告动词及其结构 <a class="header-anchor" href="#语法讲解-报告动词及其结构" aria-label="Permalink to &quot;语法讲解：报告动词及其结构&quot;">​</a></h2><p>say 常接内容从句，tell 通常先接人再接内容，claim 表示声称而不必担保真实性，confirm 表示确认某信息。suggest 可接 doing，也可接 that 从句；表示建议时，正式英语可用 should do 或原形虚拟式，不能写 suggest someone to do。不同动词不只是替换 said 的修辞工具，它们会改变信息来源与可信度的呈现。报道时须匹配原说话人的言语行为，避免把推测写成确认，或把建议写成命令。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The reporter stated the figures, while the campaigner claimed that they showed a wider problem.</p></blockquote><p>记者陈述了数字，而倡议者声称这些数字反映了更广泛的问题。</p><p>stated 与 claimed 区分陈述和观点；they 回指 figures，后半结论归属于 campaigner。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>She suggested me to write 错误；可写 She suggested that I write 或 She suggested writing，视执行者是否需要明确。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>在 residents said 和 has not yet confirmed 上重读，回听能否仅凭这些来源词区分事实状态。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The newspaper published photographs of the damaged bridge. Residents said that repairs had been delayed. The council has not yet confirmed the proposed reopening date.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句报道摘要，区分观察、引用和未证实内容。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>可见材料、居民说法、机构尚未确认分别标注，避免混成一个确定结论。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>例句中“更广泛的问题”是谁的判断？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 倡议者的判断。</p><p><strong>解析：</strong> claimed that 明确归属。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>改正：He told that the report was ready.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> He said that the report was ready.</p><p><strong>解析：</strong> tell 需先说明接收信息的人，或改用 say。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>把“她建议核实数字”译成英语。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> She suggested checking the figures.</p><p><strong>解析：</strong> suggest 可接动名词。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：报告动词及其结构。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-044">上一课</a> · <a href="/life/english/new-concept/book-3/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-03/lesson-046">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const g=t(i,[["render",s]]);export{u as __pageData,g as default};
